questionvariables.text:
x1:rand_with_step(30,80,1);
x2:rand_with_prohib(30,80,[x1]);
x3:rand_with_prohib(30,80,[x1,x2]);
x4:rand_with_prohib(30,80,[x1,x2,x3]);
x5:rand_with_prohib(30,80,[x1,x2,x3,x4]);
x6:rand_with_prohib(30,80,[x1,x2,x3,x4,x5]);
x7:rand_with_prohib(30,80,[x1,x2,x3,x4,x5,x6]);
x8:rand_with_prohib(30,80,[x1,x2,x3,x4,x5,x6,x7]);
x_coord_list:[x1,x2,x3,x4,x5,x6,x7,x8];
x_coord_list_ord:sort(x_coord_list);

rank_x:makelist(0,i,1,8);

for i:1 thru 8 do (
    for j:1 thru 8 do (
        if x_coord_list[i]=x_coord_list_ord[j] then rank_x[i]:j
    )
);
y1:rand_with_step(30,60,1);
y2:rand_with_prohib(30,60,[y1]);
y3:rand_with_prohib(30,60,[y1,y2]);
y4:rand_with_prohib(30,60,[y1,y2,y3]);
y5:rand_with_prohib(30,60,[y1,y2,y3,y4]);
y6:rand_with_prohib(30,60,[y1,y2,y3,y4,y5]);
y7:rand_with_prohib(30,60,[y1,y2,y3,y4,y5,y6]);
y8:rand_with_prohib(30,60,[y1,y2,y3,y4,y5,y6,y7]);
y_coord_list:[y1,y2,y3,y4,y5,y6,y7,y8];
y_coord_list_ord:sort(y_coord_list);
rank_y:makelist(0,i,1,8);

for i:1 thru 8 do (
    for j:1 thru 8 do (
        if y_coord_list[i]=y_coord_list_ord[j] then rank_y[i]:j
    )
);
r_1:(rank_x[1]-rank_y[1])^2;
r_2:(rank_x[2]-rank_y[2])^2;
r_3:(rank_x[3]-rank_y[3])^2;
r_4:(rank_x[4]-rank_y[4])^2;
r_5:(rank_x[5]-rank_y[5])^2;
r_6:(rank_x[6]-rank_y[6])^2;
r_7:(rank_x[7]-rank_y[7])^2;
r_8:(rank_x[8]-rank_y[8])^2;

d_squared:[r_1,r_2,r_3,r_4,r_5,r_6,r_7,r_8]; 


/*sum(d_squared)*/
n:sum(d_squared[i],i,1,8); 
total_d_squared:n;
ta1:decimalplaces(1-((6*total_d_squared)/504),3);
ta3:random_permutation([[1,true,"There is a moderate negative association between the two sets of variables."], [2,false, "There is a weak positive association between the two sets of variables."], [3,false, "There is no significant correlation between the two sets of variables.
"], [4,false, "There is a strong positive association between the two sets of variables."]]);

/*Section B*/
ta_21: if ta1 > 0 then "There is a positive association between the two sets of variables." elseif ta1 < 0 then "There is a negative association between the two sets of variables." elseif ta1 = 0 then "No correlation" else "None of the options apply";
ta_22: if ta1 > 0 then " There is a negative association between the two sets of variables." elseif ta1 < 0 then "TThere is a positive association between the two sets of variables." else "None of the options apply";

ta3:random_permutation([[ta_21, true],[ta_22, false],["No correlation", false]]);
